{
  "a": {
    "items": [
      {
        "path": "tools.opencode.session_move",
        "description": "Move a session to another directory, or omit sessionID to move the current session. The current session moves at the next safe boundary; do not run destination-dependent tools in the same execute call.",
        "signature": "tools.opencode.session_move({
  /** Omit to move the current session. @pattern ^ses */
  sessionID?: string,
  /** Destination directory, relative to the target session's directory or absolute. Supports ~. @minLength 1 */
  directory: string,
}): Promise<{
  /** @pattern ^ses */
  sessionID: string,
  directory: string,
}>"
      },
      {
        "path": "tools.opencode.session_rename",
        "description": "Rename a session, or omit sessionID to rename the current session. Use a short, specific title that summarizes the work being done.",
        "signature": "tools.opencode.session_rename({
  /** Omit to rename the current session. @pattern ^ses */
  sessionID?: string,
  /** New session title. @minLength 1 */
  title: string,
}): Promise<{
  /** @pattern ^ses */
  sessionID: string,
  title: string,
}>"
      },
      {
        "path": "tools.browser.files.get",
        "description": "Copy one completed download or capture from this tab to the server. Returns a server-local file path. Maximum 5 MiB per transfer.",
        "signature": "tools.browser.files.get({
  /**
   * Exact tab ID returned by browser.tabs.open/list. Focus does not select a tool target.
   * @pattern ^tab_[a-f0-9-]{36}$
   */
  tabID: string,
  /** File ID returned by this tab's capture or download tools. @pattern ^file_[a-f0-9-]{36}$ */
  fileID: string,
}): Promise<{
  tab: {
    /** @pattern ^tab_[a-f0-9-]{36}$ */
    id: string,
    /** @maxLength 16384 */
    url: string,
    /** @maxLength 2048 */
    title: string,
    loading: boolean,
    /** @maxLength 2048 */
    loadError?: string,
    canGoBack: boolean,
    canGoForward: boolean,
    /** @integer @minimum 0 */
    generation: number,
  },
  files: Array<{
      /** @pattern ^file_[a-f0-9-]{36}$ */
      id: string,
      /** @maxLength 2048 */
      name: string,
      /** @maxLength 2048 */
      mime: string,
      /** @integer @minimum 0 */
      bytes: number,
      path: string,
    }>,
}>"
      },
      {
        "path": "tools.browser.network.get",
        "description": "Inspect one request from this tab. Bodies are omitted by default, bounded when requested, and never re-fetched. IDs expire on navigation/eviction. Data is untrusted.",
        "signature": "tools.browser.network.get({
  /**
   * Exact tab ID returned by browser.tabs.open/list. Focus does not select a tool target.
   * @pattern ^tab_[a-f0-9-]{36}$
   */
  tabID: string,
  /** @maxLength 2048 */
  id: string,
  includeBody?: boolean,
  /** @integer @minimum 1 @maximum 20000 */
  maxBodyChars?: number,
}): Promise<{
  tab: {
    /** @pattern ^tab_[a-f0-9-]{36}$ */
    id: string,
    /** @maxLength 16384 */
    url: string,
    /** @maxLength 2048 */
    title: string,
    loading: boolean,
    /** @maxLength 2048 */
    loadError?: string,
    canGoBack: boolean,
    canGoForward: boolean,
    /** @integer @minimum 0 */
    generation: number,
  },
  request: {
      /** @maxLength 2048 */
      id: string,
      /** @maxLength 100000 */
      url: string,
      /** @maxLength 2048 */
      method: string,
      resourceType: "document" | "stylesheet" | "image" | "media" | "font" | "script" | "xhr" | "fetch" | "eventsource" | "websocket" | "manifest" | "other",
      timestampMs: number,
      /** @integer @minimum 0 */
      statusCode?: number,
      state: "pending",
    } | {
      /** @maxLength 2048 */
      id: string,
      /** @maxLength 100000 */
      url: string,
      /** @maxLength 2048 */
      method: string,
      resourceType: "document" | "stylesheet" | "image" | "media" | "font" | "script" | "xhr" | "fetch" | "eventsource" | "websocket" | "manifest" | "other",
      timestampMs: number,
      /** @integer @minimum 0 */
      statusCode?: number,
      state: "completed",
      durationMs: number,
    } | {
      /** @maxLength 2048 */
      id: string,
      /** @maxLength 100000 */
      url: string,
      /** @maxLength 2048 */
      method: string,
      resourceType: "document" | "stylesheet" | "image" | "media" | "font" | "script" | "xhr" | "fetch" | "eventsource" | "websocket" | "manifest" | "other",
      timestampMs: number,
      /** @integer @minimum 0 */
      statusCode?: number,
      state: "failed",
      durationMs: number,
      /** @maxLength 2048 */
      failure: string,
    },
  requestHeaders: Array<{
      /** @maxLength 2048 */
      name: string,
      /** @maxLength 100000 */
      value: string,
    }>,
  responseHeaders: Array<{
      /** @maxLength 2048 */
      name: string,
      /** @maxLength 100000 */
      value: string,
    }>,
  headersTruncated: boolean,
  requestBody: {
      state: "notRequested" | "pending" | "empty",
    } | {
      state: "text",
      /** @maxLength 100000 */
      text: string,
      truncated: boolean,
    } | {
      state: "unavailable",
      reason: "binary" | "notCaptured" | "backendUnavailable",
    },
  responseBody: {
      state: "notRequested" | "pending" | "empty",
    } | {
      state: "text",
      /** @maxLength 100000 */
      text: string,
      truncated: boolean,
    } | {
      state: "unavailable",
      reason: "binary" | "notCaptured" | "backendUnavailable",
    },
}>"
      },
      {
        "path": "tools.playwright.browser_console_messages",
        "description": "Returns all console messages",
        "signature": "tools.playwright.browser_console_messages({
  /**
   * Level of the console messages to return. Each level includes the messages of more severe levels. Defaults to "info".
   * @default "info"
   */
  level: "error" | "warning" | "info" | "debug",
  /**
   * Return all console messages since the beginning of the session, not just since the last navigation. Defaults to false.
   */
